'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';
import { useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';

const SHIFT_PX = 8;

const SLIDE_TRANSITION: Transition = { duration: 0.18, ease: [0.2, 0, 0, 1] };

const SLIDE_VARIANTS: Variants = {
  enter: (direction: number) => {
    const offset = direction * SHIFT_PX;
    return { opacity: 0, y: offset };
  },
  visible: { opacity: 1, y: 0 },
  exit: (direction: number) => {
    const offset = direction * SHIFT_PX;
    return { opacity: 0, y: -offset };
  },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

function variantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SLIDE_VARIANTS;
}

function directionOf(previous: number, next: number) {
  if (next > previous) {
    return 1;
  }
  return -1;
}

type Shown = { value: number; direction: number };

type SlidingCountProps = {
  value: number;
  /** Writes the figure in words, with its singular branch. */
  format: (value: number) => string;
  className?: string;
};

/** A figure the person just changed: it slides in the direction of the change. */
export function SlidingCount({ value, format, className }: SlidingCountProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const [shown, setShown] = useState<Shown>({ value, direction: 1 });
  const text = format(value);

  if (shown.value !== value) {
    const direction = directionOf(shown.value, value);
    setShown({ value, direction });
  }

  return (
    <span
      className={cn(
        'relative inline-flex overflow-hidden tabular-nums',
        className
      )}
    >
      <AnimatePresence
        mode='popLayout'
        initial={false}
        custom={shown.direction}
      >
        <motion.span
          key={text}
          custom={shown.direction}
          variants={variantsOf(shouldReduceMotion)}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={SLIDE_TRANSITION}
          className='whitespace-nowrap'
        >
          {text}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };

const SWAP_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

function variantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

type SwapProps = {
  /** Changes when the content becomes another one. */
  swapKey: string;
  className?: string;
  children: React.ReactNode;
};

/** An icon that becomes another: the old one shrinks out of focus while the new one settles. */
export function Swap({ swapKey, className, children }: SwapProps) {
  const shouldReduceMotion = usePrefersReducedMotion();

  return (
    <AnimatePresence mode='popLayout' initial={false}>
      <motion.span
        key={swapKey}
        variants={variantsOf(shouldReduceMotion)}
        initial='enter'
        animate='visible'
        exit='exit'
        transition={SWAP_TRANSITION}
        className={cn('flex', className)}
      >
        {children}
      </motion.span>
    </AnimatePresence>
  );
}

import { cn } from '@/registry/ndeko/lib/utils';
import { MeshTile } from '@/registry/ndeko/ui/mesh-tile';

const SIZE_CLASS = {
  sm: 'size-5 rounded-[5px]',
  md: 'size-6 rounded-md',
  lg: 'size-9 rounded-lg',
} as const;

type TeamTileProps = {
  name: string;
  color: string;
  size?: keyof typeof SIZE_CLASS;
  className?: string;
};

/** A team without a logo: a picture drawn from its name, in its colour. */
export function TeamTile({
  name,
  color,
  size = 'md',
  className,
}: TeamTileProps) {
  const sizeClass = SIZE_CLASS[size];

  return (
    <MeshTile seed={name} color={color} className={cn(sizeClass, className)} />
  );
}

